window.NEMO_CONTENT = {
  projects: [
{"id":"popup","title":"순간을 기억하게 하는 팝업","category":"팝업","style":"모던","kind":"팝업","visual":"popup","lead":"짧은 순간을, 오래 기억하는 경험으로.","intro":"전시와 체험, 판매가 자연스럽게 이어지는 팝업 공간을 생각해요. 제품의 매력과 방문자의 동선을 함께 살펴봐요.","points":["체험과 전시","유연한 구성","기억에 남는 동선"],"sections":[["경험의 흐름","입장부터 제품을 만나고 체험하는 순서를 정리해요. 작은 공간에서도 편하게 움직이도록 생각해요.","popup"]]},
{"id":"branding","title":"공간으로 이어지는 브랜드","category":"브랜딩","style":"모던","kind":"브랜딩","visual":"a-cafe","lead":"브랜드의 이야기가 공간에서도 이어져요.","intro":"브랜드의 성격과 고객에게 전하고 싶은 인상을 정리해요. 색과 소재, 공간의 디테일로 한결같은 경험을 만들어요.","points":["브랜드의 방향","일관된 색감","공간의 디테일"],"sections":[["브랜드의 방향","브랜드가 전하고 싶은 이야기를 듣고 색과 소재, 형태로 연결해요. 공간 안에서 같은 인상이 이어지도록 해요.","a-cafe"]]},
{"id":"styling","title":"취향을 완성하는 스타일링","category":"스타일링","style":"내추럴","kind":"스타일링","visual":"a-material","lead":"좋아하는 색과 소재로 일상의 분위기를 바꿔요.","intro":"가구와 조명, 패브릭과 소품의 조합을 살펴봐요. 기존 공간의 장점을 살리면서 취향에 맞는 분위기를 더해요.","points":["가구의 조합","색과 질감","편안한 분위기"],"sections":[["취향의 조합","좋아하는 색과 소재를 중심으로 가구와 소품의 균형을 맞춰요. 쓰임과 분위기를 함께 살펴봐요.","a-material"]]},
    {id:'office',title:'일의 리듬을 만드는 오피스',category:'사무',style:'미니멀',kind:'오피스',visual:'office',lead:'혼자 집중하고, 함께 생각하는 공간.',intro:'집중하는 자리와 대화하는 자리를 나눠 일의 흐름을 편안하게 만들어요. 팀의 규모와 업무 방식에 맞춘 사무 공간 콘셉트예요.',points:['집중과 협업의 균형','유연한 배치','편안한 업무 동선'],sections:[['집중하는 자리','모니터의 눈부심과 이동 동선을 살피고, 업무에 필요한 수납을 가까이에 둬요. 오래 머무는 자리의 편안함부터 생각해요.','office'],['함께 생각하는 자리','짧은 대화와 긴 회의에 맞는 자리를 구분해요. 서로의 일을 방해하지 않으면서 자연스럽게 의견을 나눌 수 있도록 연결해요.','a-material'],['변화에 맞는 배치','팀의 인원과 업무 방식이 바뀌어도 유연하게 쓸 수 있도록 가구와 동선을 정리해요. 전원과 조명, 수납도 함께 살펴봐요.','office']]},
    {id:'living',title:'자연을 들이는 거실',category:'주거',style:'내추럴',kind:'거실',visual:'photo',lead:'창밖의 풍경이 실내의 분위기로 이어져요.',intro:'큰 창으로 들어오는 빛, 따뜻한 원목, 편안한 소파. 자연을 가까이 두고 오래 머물고 싶은 거실을 생각했어요.',points:['풍경을 향한 시선','따뜻한 원목','여유 있는 동선'],sections:[['빛과 풍경','창을 향한 시선을 가리지 않도록 가구의 높이와 위치를 정해요. 커다란 창 자체가 공간의 중심이 될 수 있어요.','photo'],['소재와 질감','원목의 결, 부드러운 패브릭, 차분한 크림색을 연결해 실내와 자연의 경계가 편안하게 이어지도록 해요.','a-material'],['머무는 자리','소파와 테이블 사이의 여유를 생각해요. 가구를 채우기보다 일상에서 편하게 움직이고 쉴 수 있는 자리를 남겨요.','a-home']]},
    {id:'home',title:'취향이 머무는 집',category:'주거',style:'내추럴',kind:'거실',visual:'a-home',lead:'좋아하는 것들이 자연스럽게 어울리는 집.',intro:'둥근 소파와 작은 테이블, 따뜻한 노란 포인트. 취향을 담으면서 매일의 생활에 편안함을 더하는 거실 콘셉트예요.',points:['부드러운 곡선','크림과 옐로','편안한 휴식'],sections:[['생활의 중심','대화하고 쉬고 책을 읽는 장면을 먼저 떠올려요. 좋아하는 활동에 맞춰 거실의 중심을 정해요.','a-home'],['취향의 조합','색을 여러 개 더하기보다 기본 톤과 포인트 톤을 나눠요. 질감이 다른 소재를 함께 사용하면 공간이 풍부해져요.','a-material']]},
    {id:'cafe',title:'다시 찾고 싶은 카페',category:'상업',style:'내추럴',kind:'카페',visual:'a-cafe',lead:'처음 들어온 순간부터, 편하게 머무는 순간까지.',intro:'노란 카운터와 원목 테이블, 부드러운 조명. 브랜드의 첫인상과 손님이 머무는 경험을 함께 생각한 카페 콘셉트예요.',points:['선명한 첫인상','편리한 주문 동선','따뜻한 소재'],sections:[['브랜드의 첫인상','카운터에 포인트 컬러를 모아 시선이 자연스럽게 향하도록 해요. 공간 안에서 브랜드의 분위기가 일관되게 이어지도록 생각해요.','a-cafe'],['머무는 경험','주문하고 기다리고 자리에 앉는 흐름을 정리해요. 직원과 손님의 움직임을 함께 고려한 공간을 그려요.','a-material']]},
    {id:'materials',title:'손끝으로 느끼는 취향',category:'주거',style:'모던',kind:'소재',visual:'a-material',lead:'색보다 먼저, 손끝에 남는 감각.',intro:'원목과 크림색 표면, 차분한 세이지 패브릭. 색과 질감의 조화로 만드는 공간의 분위기를 살펴봐요.',points:['원목의 결','차분한 세이지','매트한 표면'],sections:[['색의 균형','큰 면적의 색을 먼저 정하고, 작은 소품의 색으로 변화를 더해요. 공간 전체에 쓰일 톤을 하나의 묶음으로 살펴봐요.','a-material'],['생활에 맞는 선택','소재를 고를 때는 감촉뿐 아니라 사용하는 장면도 생각해요. 자주 닿는 곳과 오래 바라보는 곳에 어울리는 질감을 구분해요.','a-home']]},
    {id:'brand',title:'분위기가 되는 디테일',category:'상업',style:'모던',kind:'브랜드 공간',visual:'photo',lead:'빛과 소재가 만드는, 오래 기억되는 첫인상.',intro:'공간을 채우는 작은 요소들이 브랜드의 분위기를 만들어요. 빛과 원목 소재를 연결하는 디자인 방향을 살펴봐요.',points:['빛의 방향','일관된 색감','기억에 남는 소재'],sections:[['빛의 장면','자연광이 들어오는 자리와 조명이 필요한 자리를 나눠 생각해요. 밝기의 차이가 공간의 깊이를 만들 수 있어요.','photo'],['브랜드의 질감','브랜드를 떠올릴 때 느끼고 싶은 감각을 소재로 표현해요. 색과 형태를 반복하면 공간 안에서 분위기가 이어져요.','a-material']]},
    {id:'rest',title:'일상의 작은 쉼표',category:'주거',style:'미니멀',kind:'휴식 공간',visual:'a-home',lead:'바쁜 하루 사이, 잠시 머물 수 있는 자리.',intro:'한쪽의 작은 자리에서도 충분히 편안하게 쉴 수 있어요. 시선과 동선을 정리해 휴식에 집중하는 공간을 생각했어요.',points:['정돈된 시선','작은 가구','편안한 색감'],sections:[['비워두는 여유','필요한 가구만 남기고, 움직이는 자리에 여백을 둬요. 작은 공간에서도 편안한 리듬을 만들 수 있어요.','a-home'],['조용한 색감','강한 색보다 차분한 기본 톤에 질감을 더해요. 눈이 편안하게 머무는 분위기를 생각해요.','a-material']]},
    {id:'small-brand',title:'작지만 선명한 브랜드',category:'상업',style:'미니멀',kind:'매장',visual:'a-cafe',lead:'작은 공간 안에서도, 브랜드는 또렷하게.',intro:'공간의 크기보다 무엇을 보여줄지 먼저 정해요. 포인트 컬러와 간결한 동선으로 브랜드의 성격을 표현하는 매장 콘셉트예요.',points:['집중된 포인트','간결한 동선','브랜드의 색'],sections:[['하나의 중심','가장 보여주고 싶은 제품이나 장면을 중심에 둬요. 시선이 분산되지 않도록 주변의 요소를 정리해요.','a-cafe'],['작은 디테일','손잡이, 조명, 소재 같은 작은 요소에도 같은 디자인 방향을 적용해요. 작은 공간일수록 일관된 디테일이 중요해요.','a-material']]}
  ],
  stories: [
    {id:'light',category:'공간 이야기',title:'빛이 머무는 자리부터 생각해요',visual:'photo',time:'3분',lead:'같은 공간도 빛의 방향에 따라 다른 분위기가 돼요.',sections:[['창을 먼저 바라봐요','가구를 고르기 전에 하루 동안 빛이 들어오는 자리를 살펴보세요. 아침과 오후에 좋아하는 자리가 다를 수도 있어요. 자주 머무는 공간의 밝기를 기준으로 생활의 중심을 생각해봐요.'],['풍경을 가리지 않는 선택','큰 창 앞에는 낮은 가구를 두는 방법도 있어요. 창밖의 나무와 하늘이 실내의 색과 자연스럽게 연결되면, 특별한 장식 없이도 분위기가 풍부해져요.'],['하나의 공간, 여러 장면','책을 읽는 자리와 대화를 나누는 자리에는 서로 다른 빛이 어울려요. 조명을 한곳에 모으기보다 필요한 장면에 나눠 생각하면 공간에 다양한 표정을 더할 수 있어요.']]},
    {id:'materials',category:'디자인 노트',title:'색과 소재를 고르는 작은 기준',visual:'a-material',time:'4분',lead:'잘 어울리는 공간은 색뿐 아니라 질감도 연결되어 있어요.',sections:[['큰 면부터 정해요','바닥과 벽처럼 면적이 큰 부분의 톤을 먼저 정해요. 큰 면이 정리되면 가구와 작은 소품을 고르는 기준도 선명해져요.'],['질감으로 차이를 더해요','비슷한 색이라도 원목, 패브릭, 매트한 표면은 서로 다른 느낌을 만들어요. 톤을 단순하게 유지하면서 질감을 섞으면 공간이 단조롭지 않아요.'],['생활의 장면을 떠올려요','예쁜 소재를 찾는 것에서 한 걸음 더 나아가, 자주 만지는 곳과 오래 바라보는 곳을 생각해요. 취향과 쓰임을 함께 살피는 선택이 오래 편안한 공간으로 이어져요.']]},
    {id:'first-meeting',category:'네모 가이드',title:'첫 상담 전에, 이 세 가지를 떠올려보세요',visual:'a-estimate',time:'3분',lead:'완벽한 계획이 없어도 괜찮아요. 원하는 변화를 이야기하는 데서 시작해요.',sections:[['지금 가장 불편한 점','수납이 부족한지, 움직이는 동선이 어색한지, 분위기가 마음에 들지 않는지 떠올려보세요. 가장 바꾸고 싶은 부분부터 이야기하면 방향을 정하기 쉬워져요.'],['좋아하는 장면','마음에 드는 공간 사진을 몇 장 모아보세요. 같은 사진에서도 좋아하는 이유는 다를 수 있어요. 색, 소재, 빛, 가구 중 무엇이 마음에 드는지 함께 이야기해요.'],['예산과 일정','생각하고 있는 예산 범위와 원하는 시기를 알려주세요. 아직 정하지 못했다면 상담하며 함께 정리해도 괜찮아요. 가능한 변화의 범위를 차근차근 살펴봐요.']]},
    {id:'brand',category:'공간 이야기',title:'브랜드의 분위기는 공간에서도 이어져요',visual:'a-cafe',time:'3분',lead:'손님이 들어오는 순간부터 머무는 경험까지 생각해요.',sections:[['어떤 인상을 남길까요','차분함, 따뜻함, 경쾌함처럼 브랜드가 전달하고 싶은 감각을 먼저 정해요. 그 감각을 색과 소재, 가구의 형태로 연결해봐요.'],['동선도 경험이에요','입구에서 제품을 보고, 주문하고, 기다리는 흐름은 브랜드를 경험하는 과정이에요. 아름다운 장면과 편한 움직임을 함께 생각해요.'],['디테일을 연결해요','작은 표지와 손잡이, 조명에도 같은 방향을 적용해요. 공간 곳곳에 일관된 감각이 담기면 브랜드를 오래 기억하게 만들 수 있어요.']]},
    {id:'small-space',category:'디자인 노트',title:'작은 공간에 남겨두는 여유',visual:'a-home',time:'2분',lead:'더 많이 채우기보다, 잘 쓰는 것을 남겨요.',sections:[['필요한 기능부터 살펴봐요','작은 공간일수록 하고 싶은 일을 먼저 정해요. 휴식, 식사, 작업 중 어떤 활동이 중심인지에 따라 가구의 크기와 배치가 달라져요.'],['여백도 공간의 일부예요','가구 사이에 움직일 자리를 남겨요. 시선을 가리는 요소를 줄이고 수납을 한쪽에 정리하면 같은 공간도 더 편하게 느껴질 수 있어요.'],['포인트는 간결하게','좋아하는 색이나 소재를 한두 곳에 모아보세요. 요소를 줄여도 취향은 또렷하게 담을 수 있어요.']]},
    {id:'process',category:'네모 가이드',title:'상담부터 완성까지, 함께 살펴보는 과정',visual:'a-complete',time:'3분',lead:'처음의 생각을 매일의 공간으로 연결해요.',sections:[['듣고, 살펴봐요','원하는 변화와 공간의 조건을 이야기해요. 이어서 실제 크기와 구조를 살펴보고, 필요한 범위를 함께 정리해요.'],['방향을 함께 정해요','동선과 색감, 소재를 연결해 생활이나 브랜드에 맞는 방향을 정해요. 좋아하는 부분과 걱정되는 부분을 편하게 이야기해주세요.'],['마지막까지 확인해요','설계한 방향을 바탕으로 진행 상황과 디테일을 함께 살펴봐요. 상담에서 나눈 생각이 실제 공간에서 어떻게 이어지는지 확인해요.']]}
  ]
};
